[{"order":1,"type":"heading","text":"Playwright Test Runner Configuration and Projects"},{"order":2,"type":"paragraph","text":"Playwright Test provides a powerful, highly customizable test runner designed to handle complex end-to-end testing scenarios. At the heart of this runner is the configuration file, typically named playwright.config.ts, which allows you to define global settings, timeouts, reporters, and crucially, multiple testing projects."},{"order":3,"type":"subheading","text":"Understanding the Configuration File"},{"order":4,"type":"paragraph","text":"The configuration file exports a configuration object using the defineConfig function. This object dictates how tests are discovered, executed, and reported across your entire test suite."},{"order":5,"type":"code","text":"import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './tests',
  timeout: 30 * 1000,
  expect: {
    timeout: 5000
  },
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: 'html',
  use: {
    actionTimeout: 0,
    baseURL: 'http://localhost:3000',
    trace: 'on-first-retry',
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],
});"},{"order":6,"type":"subheading","text":"Leveraging Playwright Projects"},{"order":7,"type":"paragraph","text":"The projects property in the configuration is an array that enables you to run the same set of tests against multiple configurations, such as different browsers, viewports, authenticated states, or environments."},{"order":8,"type":"bullet_point","text":"Cross-Browser Testing: Easily execute tests on Chromium, Firefox, and WebKit simultaneously."},{"order":9,"type":"bullet_point","text":"Device Emulation: Test mobile responsiveness using predefined device descriptors."},{"order":10,"type":"bullet_point","text":"Environment Segregation: Configure separate base URLs or authentication setups for staging versus production."},{"order":11,"type":"subheading","text":"Configuring Multiple Projects with Devices"},{"order":12,"type":"paragraph","text":"Here is an example of setting up multiple projects in playwright.config.ts to test across desktop and mobile environments:"},{"order":13,"type":"code","text":"export default defineConfig({
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
    {
      name: 'firefox',
      use: { ...devices['Desktop Firefox'] },
    },
    {
      name: 'Mobile Chrome',
      use: { ...devices['Pixel 5'] },
    },
    {
      name: 'Mobile Safari',
      use: { ...devices['iPhone 12'] },
    },
  ],
});"},{"order":14,"type":"subheading","text":"Running Specific Projects"},{"order":15,"type":"paragraph","text":"When you have multiple projects defined, you can use the command line interface to target specific projects, saving time during local development."},{"order":16,"type":"code","text":"npx playwright test --project=chromium"},{"order":17,"type":"paragraph","text":"You can also target multiple projects at once by passing the --project flag multiple times or using comma separation depending on your script setup."}]
